/* Learning progress for the whole site (German, English, Spanish).
 *
 * Every page with a page-id is one item. A quiz page is done when its last quiz result is at least 70%;
 * a page without a quiz is done once it has been read to the end. Results live in this browser only
 * (localStorage keys quiz:<id> and read:<id>). progress-manifest.js lists every item; it is generated by
 * tools/site_switch.py.
 *
 * Shown: inside each page (status line), on every tile or link that previews a page (score badge, or
 * done/total for a section), and on each language's home page (total bar plus breakdown by area).
 */
(function () {
  var M = window.PROGRESS_MANIFEST; if (!M) return;
  var me = document.currentScript, ROOT = (me && me.getAttribute('data-root')) || '';
  var PASS = 0.7, HI = 0.9;
  var here = location.pathname.replace(/\/$/, '/index.html');
  // this page's path relative to the site root, worked out from ROOT ("../../")
  var depth = (ROOT.match(/\.\.\//g) || []).length, parts = decodeURIComponent(here).split('/');
  var SELF = parts.slice(parts.length - 1 - depth).join('/');
  var byPath = {}; M.pages.forEach(function (p) { byPath[p.path] = p; });

  function get(k) { try { return JSON.parse(localStorage.getItem(k) || 'null'); } catch (e) { return null; } }
  function set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }
  function state(p) {
    if (p.q) { var r = get('quiz:' + p.id); if (!r || !r.total) return { done: false, tried: false };
      var pct = r.score / r.total; return { done: pct >= PASS, tried: true, pct: pct, r: r }; }
    var rd = get('read:' + p.id); return { done: !!rd, tried: !!rd, read: true };
  }
  function under(dir) { // all items inside a folder ('' = whole site)
    return M.pages.filter(function (p) { return !dir || p.path.indexOf(dir + '/') === 0; });
  }
  function lang(path) { return path.indexOf('english/') === 0 ? 'english' : path.indexOf('spanish/') === 0 ? 'spanish' : 'german'; }
  function langItems(l) { return M.pages.filter(function (p) { return lang(p.path) === l; }); }
  function count(items) { var d = 0; items.forEach(function (p) { if (state(p).done) d++; }); return { done: d, total: items.length }; }
  function resolve(href) { // href relative to this page → site path
    if (!href || /^(https?:|#|mailto:)/.test(href)) return null;
    var base = SELF.split('/'); base.pop();
    href.split('#')[0].split('/').forEach(function (s) { if (s === '..') base.pop(); else if (s && s !== '.') base.push(s); });
    var p = base.join('/'); return p || 'index.html';
  }
  // A link to an index page stands for its whole folder; the German home stands for all German pages
  function itemsFor(path) {
    if (path === 'index.html') return langItems('german');
    var m = /^(.*)\/index\.html$/.exec(path);
    if (m) { var items = under(m[1]); return items.length > 1 ? items : null; }
    return null;
  }

  function el(tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }
  function bar(done, total) { var b = el('span', 'pbar'); var i = el('i'); i.style.width = (total ? 100 * done / total : 0) + '%'; b.appendChild(i); return b; }
  function badgeFor(path) {
    var items = itemsFor(path);
    if (items) {
      var c = count(items); if (!c.done) return null;
      var b = el('span', 'score pscore' + (c.done === c.total ? ' hi' : ''));
      b.appendChild(document.createTextNode((c.done === c.total ? '✓ ' : '') + c.done + '/' + c.total + ' '));
      b.appendChild(bar(c.done, c.total)); b.title = c.done + ' of ' + c.total + ' pages done';
      return b;
    }
    var p = byPath[path]; if (!p) return null;
    var s = state(p); if (!s.tried) return null;
    if (s.read) { var rb = el('span', 'score hi', '✓ read'); rb.title = 'Read to the end'; return rb; }
    var qb = el('span', 'score' + (s.pct >= HI ? ' hi' : s.done ? ' ok' : ''), (s.pct >= HI ? '✓ ' : '') + s.r.score + '/' + s.r.total);
    qb.title = 'Last quiz result' + (s.r.at ? ', ' + new Date(s.r.at).toLocaleDateString() : ''); return qb;
  }

  // 1. previews: tiles and heading links
  function previews() {
    document.querySelectorAll('.score').forEach(function (x) { x.remove(); });
    var seen = [];
    document.querySelectorAll('.home-card, h2 > a[href], .home-card a[href], .toc-list a[href]').forEach(function (n) {
      var a = n.tagName === 'A' ? n : null; if (!a) return;
      if (seen.indexOf(a) >= 0) return; seen.push(a);
      var path = resolve(a.getAttribute('href')); if (!path || path === SELF && !itemsFor(path)) return;
      var b = badgeFor(path); if (!b) return;
      var target = a.querySelector('.t') || a;
      if (a.parentNode && a.parentNode.tagName === 'H2') a.parentNode.appendChild(b); else target.appendChild(b);
    });
  }

  // 2. inside the page: status line and section progress
  function inside() {
    var old = document.getElementById('pstatus'); if (old) old.remove();
    var hero = document.querySelector('header.hero'); if (!hero) return;
    var box = el('div', 'pstatus'); box.id = 'pstatus';
    var me = byPath[SELF], items = itemsFor(SELF);
    if (SELF === 'index.html' || SELF === 'english/index.html' || SELF === 'spanish/index.html') return home(hero);
    if (items) {
      var c = count(items);
      box.appendChild(el('span', 'plabel', 'Your progress in this part'));
      box.appendChild(bar(c.done, c.total));
      box.appendChild(el('span', 'pnum', c.done + ' of ' + c.total + ' pages done'));
    } else if (me) {
      var s = state(me), dir = SELF.replace(/\/[^/]*$/, '');
      var sec = dir !== SELF ? under(dir) : [];
      box.appendChild(el('span', 'plabel', me.q ? (s.tried ? (s.done ? '✓ Done: last quiz ' + Math.round(s.pct * 100) + '%' : 'Last quiz ' + Math.round(s.pct * 100) + '%: 70% counts as done') : 'Not done yet: score 70% in the quiz below')
                                              : (s.done ? '✓ Read' : 'Read to the end to mark this page as done')));
      if (sec.length > 1) { var c2 = count(sec); box.appendChild(bar(c2.done, c2.total)); box.appendChild(el('span', 'pnum', c2.done + ' of ' + c2.total + ' in this section')); }
    } else return;
    hero.appendChild(box);
  }

  // 3. language home: total and breakdown
  function home(hero) {
    var l = lang(SELF), all = langItems(l), c = count(all);
    var card = el('div', 'pcard card'); card.id = 'pstatus';
    var head = el('div', 'phead');
    head.appendChild(el('strong', null, 'Your progress'));
    head.appendChild(el('span', 'pnum', c.done + ' of ' + c.total + ' pages done · ' + Math.round(100 * c.done / (c.total || 1)) + '%'));
    card.appendChild(head); card.appendChild(bar(c.done, c.total));
    var groups = {}; all.forEach(function (p) { var g = M.groupOf[p.path]; (groups[g] = groups[g] || []).push(p); });
    var list = el('div', 'pgroups');
    M.groups.filter(function (g) { return groups[g.key] && lang(g.key + '/') === l; }).forEach(function (g) {
      var gc = count(groups[g.key]), row = el('a', 'pgroup'); row.href = ROOT + g.href;
      row.appendChild(el('span', 'pg-t', g.title)); row.appendChild(bar(gc.done, gc.total)); row.appendChild(el('span', 'pnum', gc.done + '/' + gc.total));
      list.appendChild(row);
    });
    card.appendChild(list);
    card.appendChild(el('p', 'phint', 'A quiz counts as done at 70% or more; a page without a quiz counts once you read it to the end. Saved in this browser only.'));
    hero.parentNode.insertBefore(card, hero.nextSibling);
  }

  // mark pages without a quiz as read when the reader reaches the end of the text
  var mine = byPath[SELF];
  if (mine && !mine.q && !get('read:' + mine.id)) {
    var end = document.querySelector('.pager') || document.querySelector('footer');
    if (end && 'IntersectionObserver' in window) {
      var io = new IntersectionObserver(function (es) { es.forEach(function (e) { if (e.isIntersecting) { set('read:' + mine.id, { at: Date.now() }); io.disconnect(); render(); } }); });
      io.observe(end);
    }
  }
  // re-render after a quiz is checked or reset
  document.addEventListener('click', function (e) { if (e.target.closest && e.target.closest('#check, #reset')) setTimeout(render, 50); });

  function render() { inside(); previews(); }
  render();
})();
